import icontract
from typing import List

@icontract.require(lambda lst: all(lst[i] <= lst[i+1] for i in range(len(lst)-1)))
@icontract.ensure(lambda lst, target, result: result == -1 or (0 <= result < len(lst) and lst[result] == target))
@icontract.ensure(lambda lst, target, result: result != -1 or target not in lst)
def binary_search(lst: List[int], target: int) -> int:
    lo, hi = 0, len(lst) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if lst[mid] == target:
            return mid
        elif lst[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
